from adr.dist import Mixture, Normal, dot, log, abs, exp, softmax, minimum, maximum


def model(x):
    l = log(abs(x) + 1)
    h0 = minimum(maximum(-44.442 + dot(x[[70, 27, 44, 9, 2, 66]], [0.020164, 0.0046305, -0.020011, 0.022543, -0.020113, 4.1358]) + dot(x[[60, 40, 63, 36, 31, 13]], [-0.088969, -0.00063499, -0.01339, -1.2954, -0.00028365, 0.019322]) + dot(x[[11, 8, 46, 68, 45, 30]], [-0.02909, -0.015639, -1.0134, -0.015899, -1.6435, 0.025742]) + dot(x[[39, 10, 24, 14, 58, 50]], [0.00042046, 0.037269, 0.039471, 0.0078109, 0.013764, -0.0077313]) + dot(x[[56, 3, 53]], [0.51281, 0.02295, -0.015132]) + dot(l[[80, 23, 66, 8, 60, 62]], [-0.68256, -3.219, -5.1034, 0.32237, 0.77493, 1.2863]) + dot(l[[13, 11, 43, 35, 9, 73]], [-16.072, 23.699, 0.76588, 5.129, -0.7133, -3.0495]) + dot(l[[71, 3, 38, 69, 19, 78]], [2.8235, -0.59269, 0.24806, -0.46399, -0.26242, 0.30652]) + dot(l[[28]], [-0.17369]), -12.815), 2.1844)
    w = softmax(-5.4315 + -4.4067 * h0, -4.3743 + -4.1413 * h0, 2.8855 + -0.6639 * h0, 3.9308 + 3.4127 * h0, 2.9896 + 5.7991 * h0)
    return Mixture(w, [Normal(4.7082 + 0.43732 * h0, exp(1.0811 + 0.13961 * h0)), Normal(14.26 + 1.2652 * h0, exp(1.8903 + 0.12619 * h0)), Normal(23.133 + -1.5654 * h0, exp(2.3314 + -0.065421 * h0)), Normal(60.47 + 17.409 * h0, exp(2.9044 + -0.29223 * h0)), Normal(80.157 + 28.5 * h0, exp(1.6285 + 0.59507 * h0))])
